options.getOption:
// Active service alerts by route: the twelve routes with the most alerts in
// effect right now (and the picked routes, if they have any), in the selected modes, each bar split by what the alert
// does (service cut or delayed, detour or stop moved, accessibility, other).
// An alert that names three routes counts on each of them.
//
// Clicking a bar picks that route in the `route` variable, as the Route
// dropdown does: the map, the bunching table and the subway history follow it.
// Clicking it again goes back to all routes. The chart does not filter itself
// by route, so the other routes stay in grey to pick another.
// Columns: `route`, `mode`, `total`, and one per effect group (EFFECTS).
// @constants begin
const VAR = 'route';
// Written literally so that Grafana redraws the panel when it changes.
const PICKED = '${route}';
const ALL = '$__all';
const EFFECTS = [
  { field: 'Service cut or delayed', color: 'red' },
  { field: 'Detour or stop moved', color: 'orange' },
  { field: 'Accessibility', color: 'blue' },
  { field: 'Other', color: 'rgba(128, 128, 128, 0.7)' },
];
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;
const paint = (c) => (c.startsWith('rgba') ? c : theme.visualization.getColorByName(c));

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
// ECharts draws a category axis bottom up: reversed, the most alerts on top.
const routes = col('route').map(String).reverse();
const modes = col('mode').reverse();
const totals = col('total').map(Number).reverse();
const counts = Object.fromEntries(EFFECTS.map((e) => [e.field, col(e.field).map(Number).reverse()]));

// `${route}` is the all-value ('__all__') when nothing is picked, one route
// when one is, `{a,b}` when several are picked in the dropdown.
const raw = context.grafana.replaceVariables(PICKED);
const picked = raw.replace(/^\{|\}$/g, '').split(',').filter((r) => r && !r.includes('__all__'));
const isPicked = (r) => picked.includes(r);

chart.off('click');
chart.on('click', (event) => {
  const route = routes[event.dataIndex];
  if (!route) return;
  const same = picked.length === 1 && picked[0] === route;
  location.partial({ ['var-' + VAR]: same ? ALL : route }, true);
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 28, top: 26, bottom: 4, containLabel: true },
  legend: {
    top: 0,
    selectedMode: false,
    data: EFFECTS.map((e) => e.field),
    textStyle: { color: muted, fontSize: 11 },
    itemWidth: 10,
    itemHeight: 10,
  },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      const rows = EFFECTS.filter((e) => counts[e.field][i] > 0)
        .map((e) => `<span style="color:${paint(e.color)}">●</span> ${e.field}: <b>${counts[e.field][i]}</b>`)
        .join('<br/>');
      const hint = isPicked(routes[i]) && picked.length === 1 ? 'click to show all routes' : 'click to pick this route';
      return `<b>${routes[i]}</b> · ${modes[i]}<br/>${totals[i]} active alerts<br/>${rows}<br/><span style="opacity:.7">${hint}</span>`;
    },
  },
  xAxis: {
    type: 'value',
    minInterval: 1,
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: {
    type: 'category',
    data: routes.map((r) => ({ value: r, textStyle: isPicked(r) ? { color: text, fontWeight: 'bold' } : {} })),
    axisTick: { show: false },
    axisLabel: { color: muted, fontSize: 11, interval: 0 },
  },
  series: EFFECTS.map((e) => ({
    name: e.field,
    type: 'bar',
    stack: 'alerts',
    barWidth: '65%',
    cursor: 'pointer',
    color: paint(e.color),
    data: counts[e.field].map((v, i) => ({
      value: v || null,
      itemStyle: { color: paint(e.color), opacity: picked.length && !isPicked(routes[i]) ? 0.3 : 1 },
    })),
  })).concat([
    // The total at the end of each bar.
    {
      type: 'bar',
      stack: 'alerts',
      silent: true,
      data: totals.map(() => 0),
      label: { show: true, position: 'right', color: muted, fontSize: 11, formatter: (p) => totals[p.dataIndex] },
      tooltip: { show: false },
    },
  ]),
};

